css:
.doc-page .cvc{--ac:#92cddc;--ac2:#d8e4bc;font-family:'Roboto','Hind Siliguri',Calibri,Arial,sans-serif;font-size:.93em;line-height:1.35;color:#1b1b1b}
.doc-page .cvc.theme-teal{--ac:#86d3c9;--ac2:#d5efeb}.doc-page .cvc.theme-green{--ac:#b5d99c;--ac2:#e4f1d8}.doc-page .cvc.theme-slate{--ac:#cfd5dc;--ac2:#eceff2}.doc-page .cvc.theme-rose{--ac:#f4bccb;--ac2:#fde6ec}.doc-page .cvc.theme-gold{--ac:#f2d78f;--ac2:#fbf1d3}
.doc-page .cvc-head{display:flex;justify-content:space-between;align-items:flex-start;gap:14px;margin-bottom:6px}
.doc-page .cvc-head-text{flex:1;text-align:center;padding-top:4px}
.doc-page .cvc-h1{font-size:1.05em;letter-spacing:.18em;text-transform:uppercase;color:#5b6570;font-weight:500}
.doc-page .cvc-name{font-size:1.85em;font-weight:700;color:#14284b;text-transform:uppercase;line-height:1.15;margin:3px 0}
.doc-page .cvc-headline{font-size:1.05em;font-weight:500;color:#2f6f8f;margin-bottom:2px}
.doc-page .cvc-contact{font-size:1.02em;font-weight:500}
.doc-page .cvc-photo{flex:0 0 auto;width:34mm;height:42mm;border:1px solid #6b7280;display:flex;align-items:center;justify-content:center;text-align:center;font-size:.7em;color:#9aa1a9;text-transform:uppercase;overflow:hidden;background:#fff}
.doc-page .cvc-photo img{width:100%;height:100%;object-fit:cover;display:block}
.doc-page .cvc-bar{background:var(--ac);font-weight:700;text-transform:uppercase;font-size:.95em;padding:2px 8px;margin:11px 0 6px;letter-spacing:.02em;-webkit-print-color-adjust:exact;print-color-adjust:exact;break-after:avoid}
.doc-page .cvc-p{text-align:justify;margin:0 0 4px}
.doc-page .cvc-info{width:100%;border-collapse:collapse}
.doc-page .cvc-info td{padding:1.5px 0;vertical-align:top}
.doc-page .cvc-info td:first-child{width:27%}
.doc-page .cvc-info td:nth-child(2){width:3%;text-align:center}
.doc-page .cvc-table{width:100%;border-collapse:collapse;text-align:center;margin-bottom:2px}
.doc-page .cvc-table th{background:var(--ac2);border:1px solid #222;padding:3px 6px;font-weight:700;-webkit-print-color-adjust:exact;print-color-adjust:exact}
.doc-page .cvc-table td{border:1px solid #222;padding:3px 6px}
.doc-page .cvc-table tr{break-inside:avoid}
.doc-page .cvc-sign{display:flex;justify-content:space-between;align-items:flex-end;margin-top:26px;break-inside:avoid}
.doc-page .cvc-sigline{border-top:1px solid #222;min-width:170px;text-align:center;padding-top:3px}
